import json,os
d={x['file']:int(x['size'] or 0) for x in json.load(open('raw/run_files.json'))['files']}
names=open('raw/quicklook_list.txt').read().split()
bad=[n for n in names if os.path.getsize('quicklook/'+n.replace('/','__'))!=d[n]]
print('size mismatches',bad)
mag={}
for n in names:
    b=open('quicklook/'+n.replace('/','__'),'rb').read(6)
    mag.setdefault(b[:4],0); mag[b[:4]]+=1
print(mag)
